"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([["358"],{1895(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome-to-meteostack","metadata":{"permalink":"/blog/welcome-to-meteostack","editUrl":"https://github.com/meteostack/docs/tree/master/packages/create-docusaurus/templates/shared/blog/2026-06-01-welcome/index.mdx","source":"@site/blog/2026-06-01-welcome/index.mdx","title":"Welcome to MeteoStack","description":"What is MeteoStack?","date":"2026-05-30T00:00:00.000Z","tags":[{"inline":false,"label":"MeteoStack","permalink":"/blog/tags/meteostack","description":"Everything MeteoStack"}],"readingTime":1.16,"hasTruncateMarker":true,"authors":[{"name":"William Dawson","title":"Project lead","url":"https://wtdawson.info","page":{"permalink":"/blog/authors/mrbisquit"},"socials":{"github":"https://github.com/mrbisquit","instagram":"https://instagram.com/wtdawson9/","website":"https://wtdawson.info/"},"imageURL":"https://github.com/mrbisquit.png","key":"mrbisquit"}],"frontMatter":{"slug":"welcome-to-meteostack","title":"Welcome to MeteoStack","authors":["mrbisquit"],"tags":["meteostack"],"date":"2026-05-30T00:00:00.000Z"},"unlisted":false,"lastUpdatedAt":1786279618000,"lastUpdatedBy":"William"},"content":"## What is MeteoStack?\\nMeteoStack is an open-source project designed help people collect weather data\\nusing a custom self-built weather station.\\n\\n| <img src=\\"/img/MeteoStack.png\\" width={256} height={256} /> | <video width=\\"320\\" height=\\"240\\" loop autoPlay><source src=\\"/img/loading.webm\\" type=\\"video/webm\\" /></video> |\\n|-|-|\\n| Logo | Loading animation |\\n\\n(Credit for the logo design: [Samma2009](/blog/authors/samma-2009/))\\n\\n{/* truncate */}\\n\\n## Community-driven\\n\\nI intend this to be a community-driven project, and the community will be involved\\nthroughout every decision possible, polls will be held when making decisions, so\\nwatch out for them, as that\'s how you can help choose what happens with the project!\\n\\nIf you would like to join in on the decision making, please either join the\\n[Discord server](https://go.wtdawson.info/ms-ds/), and or the\\n[Serchat server](https://go.wtdawson.info/ms-sc/). This is where polls are linked to,\\nand where you can receive the latest news and announcements.\\n\\n## Little-to-no reliance on third-party dependencies\\n\\nMeteoStack will run on its own libraries where possible, to minimise the reliance on third-party dependencies,\\nthis is so that it\'s easier to manage, to update, but also for security, and for the overall quality of the software.\\n\\n## More to come soon...\\n\\nFuture blog posts may be released detailing more about the project, how you can get involved, and how you can use\\nthe project to build your own weather station."}]}}')}}]);